function invoiceDocumentHtml({settings={},reference='',saleReference='',status='PAID',customer={},date='',items=[],total=0,subtotal=null,discount=0,totalLabel='Total',invoiceType='Invoice',issued_by='',issued_by_email='',confirmed_by='',confirmed_by_email='',metaFields=null,summaryLines=null,reportMode=false}){
 const esc=invoiceEscape;
 const rows=items.map(i=>{const raw=i.unit_price_snapshot??i.box_price_snapshot??i.unit_price;return `<tr><td>${esc(i.product_name||i.product_name_snapshot||'Product')}${i.report_detail?`<small class="item-detail">${esc(i.report_detail)}</small>`:''}</td><td>${esc(i.quantity_label||i.quantity||i.confirmed_boxes||i.quantity_units||'')}</td><td class="money">${raw==null?'Pending branch review':esc(money(raw))}</td><td class="money">${i.line_total==null?'Pending':esc(money(i.line_total))}</td></tr>`}).join('');
 const customerDisplayName=customer.pharmacy_name||customer.name||customer.full_name||'Walk-in customer';const customerAddress=customer.pharmacy_address||customer.address||'';const metaMarkup=metaFields?`<div class="meta">${metaFields.map(x=>`<section><b>${esc(x.label)}</b>${esc(x.value)}</section>`).join('')}</div>`:`<div class="meta"><section><b>Customer</b>${esc(customerDisplayName)}<br>${customerAddress?`${esc(customerAddress)}<br>`:''}${esc(customer.email||'')}<br>${esc(customer.phone||'')}</section><section><b>Sale / order</b>${esc(saleReference||reference)}</section><section><b>Date</b>${esc(date?new Date(date).toLocaleDateString():new Date().toLocaleDateString())}</section></div>`;
 const summaryMarkup=summaryLines?`<div class="total"><b>${summaryLines.map(x=>`${esc(x.label)}: ${esc(x.value)}`).join('<br>')}</b></div>`:`<div class="total"><b>${subtotal===null?'':`Subtotal: ${esc(money(subtotal))}<br>`}${Number(discount)>0?`Discount: -${esc(money(discount))}<br>`:''}${esc(totalLabel)}: ${esc(money(total))}</b></div>`;
 const payment=!reportMode&&settings.payment_instructions?`<section class="payment-card"><h3>Payment instructions</h3><div>${esc(settings.payment_instructions).replace(/\n/g,'<br>')}</div></section>`:'';
 const website=settings.website_url?`<div>Website: <a href="${esc(settings.website_url)}">${esc(settings.website_url)}</a></div>`:'';
 const home=!reportMode&&(settings.hero_title||settings.hero_text)?`<footer class="invoice-page-footer"><section class="home-intro"><b>${esc(settings.hero_title||'')}</b>${settings.hero_text?`<div>${esc(settings.hero_text)}</div>`:''}</section><span class="page-number"></span></footer>`:'';
 const contact=[settings.address,settings.location,settings.contact_phone?`Phone: ${settings.contact_phone}`:'',settings.contact_email?`Email: ${settings.contact_email}`:'',website].filter(Boolean).map(x=>`<div>${x===website?x:esc(x)}</div>`).join('');
 return `<!doctype html><html><head><meta charset="utf-8"><title>${esc(settings.pharmacy_name||'Pharmacy')} - ${esc(invoiceType)} ${esc(reference)}</title><style>@page{size:A4;margin:12mm}*{box-sizing:border-box}body{font:11px Arial,sans-serif;color:#18332e;margin:0}header{display:flex;align-items:center;gap:15px;padding:0 0 12px;border-bottom:2px solid #087967}.logo{width:68px;height:68px;object-fit:contain}h1{font-size:21px;color:#087967;margin:0 0 5px}.branch-name{font-size:13px;font-weight:bold;margin:0 0 4px}.contact{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:3px 12px;color:#52635f;font-size:10px}.contact a{color:inherit}.invoice-title{display:flex;justify-content:space-between;align-items:flex-start;margin:16px 0 10px}.invoice-title h2{margin:0 0 4px;font-size:18px}.status{display:inline-block;padding:6px 9px;border:1px solid #8b9c94;border-radius:16px;color:#18332e;font-weight:bold}.meta{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:10px 0 14px}.meta section{border:1px solid #65736e;padding:8px}.meta b{display:block;font-size:9px;color:#4e6159;text-transform:uppercase;margin-bottom:4px}table{width:100%;border-collapse:collapse;border:1px solid #555}th,td{padding:7px 6px;text-align:left;border:1px solid #555}th{background:#eaf5f1;color:#28554a;font-size:9px;text-transform:uppercase}.money{text-align:right;white-space:nowrap}.item-detail{display:block;margin-top:4px;color:#52635f;font-size:9px;font-weight:normal}.total{display:flex;justify-content:flex-end;margin-top:12px}.total b{min-width:190px;padding:10px;border:1px solid #555;text-align:right;font-size:15px}.payment-card{margin-top:14px;padding:10px 12px;border:1px solid #555;break-inside:avoid}.payment-card h3{font-size:12px;margin:0 0 6px}.payment-card div{line-height:1.5;white-space:normal}.invoice-page-footer{position:fixed;left:0;right:0;bottom:-5mm;display:grid;grid-template-columns:1fr auto 1fr;align-items:end;gap:8px}.home-intro{grid-column:2;text-align:center;margin:0;padding:7px 0;border-top:1px solid #777;color:#52635f;line-height:1.35;font-size:10px}.home-intro b{display:block;color:#18332e;margin-bottom:3px}.page-number{grid-column:3;justify-self:end;color:#52635f;font-size:9px}.page-number:after{content:"Page " counter(page) " of " counter(pages)}.thanks{margin-top:12px;color:#60756e}body{padding-bottom:25mm}@media print{*{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}body{color:#111}.payment-card,.meta section,table,th,td,.total b{border-color:#333!important}.contact a{color:#111;text-decoration:none}a{color:#111}tr,.payment-card,.home-intro{break-inside:avoid}.invoice-page-footer{position:fixed;bottom:-5mm;left:0;right:0}}</style></head><body><header>${settings.logo_url?`<img class="logo" src="${esc(settings.logo_url)}" alt="${esc(settings.pharmacy_name||'Pharmacy')} logo">`:''}<div><h1>${esc(settings.pharmacy_name||'Pharmacy')}</h1><div class="branch-name">${esc(settings.branch_name||settings.pharmacy_name||'Branch')}</div><div class="contact">${contact}</div></div></header><div class="invoice-title"><div><h2>${esc(invoiceType)}</h2><div>Reference: <b>${esc(reference)}</b></div></div><span class="status">${esc(status)}</span></div>${metaMarkup}<table><thead><tr><th>Product</th><th>Quantity</th><th class="money">Unit price</th><th class="money">Line total</th></tr></thead><tbody>${rows}</tbody></table>${summaryMarkup}${payment}${reportMode?'':`<div class="thanks">${issued_by?`Issued by: ${esc(issued_by)} (${esc(issued_by_email)})<br>`:''}${confirmed_by?`Confirmed by: ${esc(confirmed_by)} (${esc(confirmed_by_email)})<br>`:''}Thank you for choosing ${esc(settings.pharmacy_name||'our pharmacy')}.</div>`}${home}</body></html>`
}
function printInvoicePdf(invoice){const win=window.open('','_blank');if(!win)return false;win.document.write(invoiceDocumentHtml({settings:invoice.settings,reference:invoice.reference,saleReference:invoice.saleReference,status:invoice.status||'UNPAID DRAFT',customer:invoice.customer||{},date:invoice.date,total:invoice.total,subtotal:invoice.subtotal,discount:invoice.discount,issued_by:invoice.issued_by,issued_by_email:invoice.issued_by_email,confirmed_by:invoice.confirmed_by,confirmed_by_email:invoice.confirmed_by_email,totalLabel:invoice.totalLabel||'Invoice total',invoiceType:invoice.invoiceType||'Invoice',items:invoice.items||[]}));win.document.close();win.onload=()=>win.print();return true}
function InvoicePreviewCard({invoice,onDownload}){const s=invoice.settings||{};return <section className="invoice-preview-document"><header>{s.logo_url?<img src={s.logo_url} alt="Pharmacy logo"/>:<span className="invoice-preview-logo"><HeartPulse size={22}/></span>}<div><h3>{s.pharmacy_name||'Pharmacy'}</h3><b className="invoice-preview-branch">{s.branch_name||'Branch'}</b><p>{[s.address,s.location,s.contact_phone&&`Phone: ${s.contact_phone}`,s.contact_email&&`Email: ${s.contact_email}`].filter(Boolean).join(' | ')}{s.website_url&&<> | <a href={s.website_url}>{s.website_url}</a></>}</p></div><b className="invoice-preview-status">{invoice.status}</b></header><div className="invoice-preview-kind">{invoice.invoiceType||'Invoice'}</div><div className="invoice-preview-meta"><span><small>Reference</small><b>{invoice.reference}</b></span><span><small>Customer</small><b>{invoice.customer?.pharmacy_name||invoice.customer?.name||invoice.customer?.full_name||'Walk-in customer'}</b>{invoice.customer?.pharmacy_address&&<small>{invoice.customer.pharmacy_address}</small>}{invoice.customer?.email&&<small>{invoice.customer.email}</small>}{invoice.customer?.phone&&<small>{invoice.customer.phone}</small>}</span>{invoice.saleReference&&<span><small>Sale / order</small><b>{invoice.saleReference}</b></span>}<span><small>Date</small><b>{invoice.date?new Date(invoice.date).toLocaleDateString():'Today'}</b></span>{invoice.issued_by&&<span><small>Issued by</small><b>{invoice.issued_by}</b><small>{invoice.issued_by_email}</small></span>}{invoice.confirmed_by&&<span><small>Confirmed by</small><b>{invoice.confirmed_by}</b><small>{invoice.confirmed_by_email}</small></span>}</div><div className="table-wrap"><table><thead><tr><th className="inventory-product-col">PRODUCT</th><th>QUANTITY</th><th>UNIT PRICE</th><th>LINE TOTAL</th></tr></thead><tbody>{(invoice.items||[]).map((i,n)=><tr key={(i.product_id||i.product_id_snapshot||'item')+n}><td><b>{i.product_name||i.product_name_snapshot}</b></td><td>{i.quantity_label||i.quantity||i.confirmed_boxes||i.quantity_units}</td><td>{(i.unit_price_snapshot??i.box_price_snapshot)==null?'Pending branch review':money(i.unit_price_snapshot??i.box_price_snapshot)}</td><td>{i.line_total==null?'Pending':money(i.line_total)}</td></tr>)}</tbody><tfoot>{invoice.subtotal!=null&&<tr><th colSpan="3">Subtotal</th><th>{money(invoice.subtotal)}</th></tr>}{Number(invoice.discount||0)>0&&<tr><th colSpan="3">Discount</th><th>{money(invoice.discount)}</th></tr>}<tr><th colSpan="3">{invoice.totalLabel||'Invoice total'}</th><th>{money(invoice.total)}</th></tr></tfoot></table></div>{s.payment_instructions&&<div className="invoice-preview-payment"><b>Payment instructions</b><p>{s.payment_instructions}</p></div>}{(s.hero_title||s.hero_text)&&<div className="invoice-preview-home"><b>{s.hero_title}</b><p>{s.hero_text}</p></div>}<button type="button" className="button button-outline invoice-preview-download" onClick={onDownload||(()=>printInvoicePdf(invoice))}><ArrowDownToLine size={15}/> Print / Save PDF</button></section>}

function SnapBar({message,onDismiss}){useEffect(()=>{if(!message)return;const timer=window.setTimeout(onDismiss,5000);return()=>window.clearTimeout(timer)},[message]);if(!message)return null;const isError=/(failed|unable|error|could not|incorrect|invalid|timed out|not configured|already in use|denied|forbidden|not found|required|must be|insufficient|no .* available)/i.test(message);return <div className={`snapbar ${isError?'snapbar-error':'snapbar-success'}`} role="status" aria-live="polite"><span className="snapbar-mark"><HeartPulse size={17}/></span><span className="snapbar-message">{message}</span><button type="button" className="snapbar-close" aria-label="Dismiss notification" onClick={onDismiss}><X size={16}/></button><span className="snapbar-progress"/></div>}

function IdleTimeoutDialog({seconds,onContinue,onLogout}){return <div className="modal-backdrop idle-timeout-backdrop"><section className="product-modal idle-timeout-modal" role="alertdialog" aria-modal="true" aria-labelledby="idle-timeout-title" aria-describedby="idle-timeout-message"><div className="modal-head"><div><div className="eyebrow">SESSION TIMEOUT</div><h2 id="idle-timeout-title">Are you still there?</h2></div></div><p id="idle-timeout-message">You have been inactive for two minutes. You will be signed out in <b>{seconds} seconds</b>.</p><div className="modal-actions"><button type="button" className="button button-outline button-danger" onClick={onLogout}>Sign out now</button><button type="button" className="button button-primary" onClick={onContinue}>Continue working</button></div></section></div>}
