 const [ordersMenuOpen,setOrdersMenuOpen]=useState(false),[ordersSection,setOrdersSection]=useState('all');const [invoiceMenuOpen,setInvoiceMenuOpen]=useState(false),[invoiceSection,setInvoiceSection]=useState('all');const [financeMenuOpen,setFinanceMenuOpen]=useState(false),[financeSection,setFinanceSection]=useState('orders');
