function PublicTeamSection({settings={}}){let curated=[];try{const parsed=JSON.parse(settings.team_members||'[]');if(Array.isArray(parsed))curated=parsed.filter(m=>m&&m.name)}catch{}const members=curated.map(m=>({...m,display_name:m.name,subtitle:m.description||'Pharmacy team'}));if(!members.length)return null;return <section className="public-section team-section" id="our-team" data-reveal><div className="section-heading"><div><div className="eyebrow">OUR TEAM</div><h2>Meet our pharmacy team</h2><p>Our team is here to support your health and wellbeing.</p></div></div><div className="team-grid">{members.map((member,index)=><article className="team-card" data-reveal key={`${member.id||member.display_name}-${index}`}>{member.image_url?<img src={member.image_url} alt={member.display_name}/>:<span className="public-staff-avatar" aria-hidden="true">{member.display_name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}</span>}<div><h3>{member.display_name}</h3><p>{member.subtitle}</p></div></article>)}</div></section>}
function BranchLocationsSection({branches=[],compact=false}){return <section className={"public-section branch-locations-section "+(compact?"no-team-before":"")} id="contact" data-reveal><div className="section-heading"><div><div className="eyebrow">VISIT US</div><h2>Our branches</h2><p>Find a branch, view its location and contact the team directly.</p></div></div>{branches.length?<div className="public-branch-grid">{branches.map(branch=><article className="public-branch-card" key={branch.id}><div className="public-branch-card-heading"><div><span className="category-tag">PHARMACY BRANCH</span><h3>{branch.name}</h3></div><MapPin size={19}/></div><div className="public-branch-card-details">{branch.address&&<p><b>Address</b><span>{branch.address}</span></p>}{branch.location&&<p><b>Area</b><span>{branch.location}</span></p>}{branch.phone&&<p><b>Phone</b><a href={`tel:${branch.phone}`}>{branch.phone}</a></p>}{branch.contact_email&&<p><b>Email</b><a href={`mailto:${branch.contact_email}`}>{branch.contact_email}</a></p>}</div>{branch.map_link?<><iframe title={`${branch.name} map`} src={googleMapsEmbedUrl(branch.map_link,[branch.name,branch.location,branch.address].filter(Boolean).join(', '))} loading="lazy" referrerPolicy="no-referrer-when-downgrade" allowFullScreen/></>:<div className="branch-map-missing"><MapPin size={18}/> Map location has not been added yet.</div>}</article>)}</div>:<div className="empty-public">Branch locations will appear here when available.</div>}</section>}
function PublicLocationsPage({settings,branches=[]}){return <div className="public" style={{"--green":settings.primary_color||"#087967","--wash":settings.accent_color||"#eaf5f1"}}><PublicPageHeader settings={settings} branches={branches}/><main><section className="public-section about-hero"><div className="eyebrow">VISIT {settings.pharmacy_name||'OUR PHARMACY'}</div><h1>Pharmacy locations and contact details</h1><p>Find branch addresses, areas, phone numbers, email contacts and map directions.</p></section><BranchLocationsSection branches={branches}/></main><footer className="public-footer"><div className="footer-bottom"><span>&copy; {new Date().getFullYear()} {settings.pharmacy_name}</span><Link  to="/products">Browse products</Link><Link  to="/order-now">Order now</Link><Link  to="/about">About us</Link></div></footer></div>}
function PublicOrderNowPage({settings,branches=[]}){return <div className="public" style={{"--green":settings.primary_color||"#087967","--wash":settings.accent_color||"#eaf5f1"}}><PublicPageHeader settings={settings} branches={branches}/><main><section className="public-section about-hero"><div className="eyebrow">ORDER FROM {settings.pharmacy_name||'OUR PHARMACY'}</div><h1>Order medicines and health products</h1><p>Browse the catalogue, add products to your order and choose the branch that will prepare it. The pharmacy team will review availability and confirm your order details.</p><div className="hero-actions"><Link className="button button-primary"  to="/products">Browse products <ArrowRight size={16}/></Link><Link className="button button-outline"  to="/customer">Start an order <ArrowRight size={16}/></Link></div></section><section className="public-section"><div className="section-heading"><div><div className="eyebrow">HOW IT WORKS</div><h2>Three steps to place an order</h2></div></div><div className="service-grid"><article className="service-card"><h3>1. Choose products</h3><p>Browse the current catalogue and add the products you need.</p></article><article className="service-card"><h3>2. Select a branch</h3><p>Choose the pharmacy branch that is convenient for collection and follow up.</p></article><article className="service-card"><h3>3. Submit for review</h3><p>Sign in to send your order. The branch team will confirm product availability and next steps.</p></article></div></section><BranchLocationsSection branches={branches}/></main><footer className="public-footer"><div className="footer-bottom"><span>&copy; {new Date().getFullYear()} {settings.pharmacy_name}</span><Link  to="/products">Browse products</Link><Link  to="/locations">Branch locations</Link><Link  to="/about">About us</Link></div></footer></div>}

