function DashboardCharts({summary}){const data=summary?.daily||[],max=Math.max(1,...data.map(x=>Number(x.total||0)));return <div className="panel report-chart-panel"><div className="panel-head"><div><h2>Sales and order summary</h2><p>Daily paid totals and order activity over the last seven days</p></div><Activity size={18}/></div><div className="report-charts"><div className="chart-card"><b>Paid sales (TZS)</b><svg viewBox="0 0 560 180" role="img" aria-label="Daily paid sales chart"><line x1="35" y1="145" x2="550" y2="145" stroke="#dce8e3"/>{data.map((x,i)=>{const bar=Math.max(2,Number(x.total||0)/max*108),gap=515/data.length,w=Math.min(38,gap*.55),xx=40+i*gap;return <g key={x.day}><rect x={xx} y={145-bar} width={w} height={bar} rx="5" fill="#087967"/><text x={xx+w/2} y="164" textAnchor="middle">{String(x.day).slice(5)}</text></g>})}</svg><div className="chart-total">Today paid: <b>{money(summary?.today_paid||0)}</b></div></div><div className="chart-card"><b>Order status snapshot</b><div className="status-bars">{[['Awaiting review',summary?.submitted_orders||0,'#d39b42'],['Awaiting payment',summary?.open_orders||0,'#397ba4'],['Paid today',summary?.paid_today_count||0,'#16816f']].map(([label,n,color])=><div key={label}><span>{label}</span><i><em style={{width:`${Math.max(4,Math.min(100,Number(n)*12))}%`,background:color}}/></i><b>{n}</b></div>)}</div><div className="chart-total">Paid orders today: <b>{summary?.paid_today_count||0}</b></div></div></div></div>}
